package com.sarvam.guide.core

/**
 * Canned voice script. Every spoken line lives in app/src/main/assets/voice/<key>.wav,
 * pre-generated by tools/gen_audio.py with the Sarvam TTS API (bulbul:v3, priya).
 * The guide flow never calls chat/TTS at runtime: the vision reports the current
 * screen, we map it to a step key, and play that key's audio.
 */
object Scripts {

    /** Audio asset path for a line key in the currently selected language. */
    fun audioPath(key: String) = "voice/${Lang.code}/$key.wav"

    /** Fixed system lines (not tied to a screen). */
    val SYSTEM = listOf(
        "ask_what",
        "consent",
        "couldnt_understand",
        "risk",
        "screen_issue",
        "recovery",
        "go_home",
        "medicine",
        "offline_airplane",
        "offline_no_internet",
        "offline_provider_down",
    )

    /** Screen -> step key for "Send a photo on WhatsApp". */
    val PHOTO_SCREENS = mapOf(
        "home_screen" to "photo_open",
        "whatsapp_chatlist" to "photo_select",
        "whatsapp_chat" to "photo_attach",
        "whatsapp_attach" to "photo_gallery",
        "whatsapp_gallery" to "photo_pick",
        "whatsapp_send_preview" to "photo_send",
    )

    /** Screen -> step key for "Make a video call on WhatsApp". */
    val CALL_SCREENS = mapOf(
        "home_screen" to "call_open",
        "whatsapp_chatlist" to "call_select",
        "whatsapp_chat" to "call_videocall",
    )

    /** Screen -> step key for "Make a normal (voice) call on WhatsApp". */
    val VOICE_CALL_SCREENS = mapOf(
        "home_screen" to "call_open",
        "whatsapp_chatlist" to "call_select",
        "whatsapp_chat" to "call_voicecall",
    )

    /** Screen -> step key for "Open YouTube and play a video". */
    val PLAY_SCREENS = mapOf(
        "home_screen" to "play_open",
        "youtube_home" to "play_search",
        "youtube_video" to "play_enjoy",
    )

    /** Celebration line when the task is complete. */
    val DONE_KEYS = mapOf(
        Tasks.WHATSAPP_PHOTO to "photo_done",
        Tasks.WHATSAPP_VIDEO_CALL to "call_done",
        Tasks.WHATSAPP_VOICE_CALL to "call_done_voice",
        Tasks.YOUTUBE_PLAY to "play_done",
    )

    /** Which step key to play for the given task + reported screen. */
    fun keyFor(task: String, screen: String): String? = when (task) {
        Tasks.WHATSAPP_PHOTO -> PHOTO_SCREENS[screen]
        Tasks.WHATSAPP_VIDEO_CALL -> CALL_SCREENS[screen]
        Tasks.WHATSAPP_VOICE_CALL -> VOICE_CALL_SCREENS[screen]
        Tasks.YOUTUBE_PLAY -> PLAY_SCREENS[screen]
        else -> null
    }
}